<?= $this->extend('layouts/tenant_admin') ?><?= $this->section('content') ?><header class="page-head"><p class="eyebrow">Accountability</p><h1>Tenant audit trail</h1><p>Recent security and business-critical changes for this school.</p></header><section class="panel"><?php if($events===[]):?><div class="empty">No audit events have been recorded.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Actor</th><th>Summary</th></tr></thead><tbody><?php foreach($events as $event):?><tr><td><?= esc($event['created_at']) ?></td><td><code><?= esc($event['action']) ?></code></td><td><?= esc((string)($event['actor_user_id']??'System')) ?></td><td><?= esc($event['summary']??'') ?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section><?= $this->endSection() ?>
